		var incData json.RawMessage
		if opts.IncrementalData != nil {
			redacted, redactErr := redact.JSONLBytes(opts.IncrementalData)
			if redactErr != nil {
				return plumbing.ZeroHash, fmt.Errorf("failed to redact incremental checkpoint: %w", redactErr)
			}
